SELECT CAST(EXTRACT(MONTH FROM motos1.fecha) AS SIGNED) AS mnfechaok FROM motos1 WHERE ((motos1.categoria IN ('CAMIONES', 'CAMIONES, BUSES Y PANELES', 'MOTOCICLETAS', 'PICK UPS, VANS Y JEEPS', 'PICK-UPS', 'SUV Y JEEPS', 'VEHICULOS NUEVOS')) AND (CAST(EXTRACT(YEAR FROM motos1.fecha) AS SIGNED) >= 2010) AND (CAST(EXTRACT(YEAR FROM motos1.fecha) AS SIGNED) <= 2015)) GROUP BY mnfechaok;
